161	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
162	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
163	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
164	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
165	  const char* iceman = std::getenv("ICEMAN");
166	  if (!iceman || !*iceman) {
167	    std::fprintf(stderr,
168	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
169	                 "(export ICEMAN=<path to ICEman binary>)\n");
170	    return 2;
171	  }
172	  // Build vsim argv from the standalone template, appending user passthrough
173	  // and the JTAG port flag.
174	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
175	  if (elf.empty()) return 2;
176	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
177	  std::vector<std::string> vsim_pass = cli.passthrough;
178	  vsim_pass.push_back("--jtag-port");
179	  vsim_pass.push_back(jtag_port);
180	  std::string err;
181	  const std::vector<std::string> vsim_argv =
182	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
183	  if (!err.empty()) {
184	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
185	    return 2;
186	  }
187	  std::fprintf(stderr,
188	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
189	               jtag_port.c_str());
190	  if (fork_background(vsim_argv) < 0) {
191	    std::fprintf(stderr,
192	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
193	    return 1;
194	  }
195	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
196	  // Wait for the port to be LISTENing before launching the debugger (it does not
197	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
198	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
199	  // but launch anyway if it never appears.
200	  if (const int pnum = std::atoi(jtag_port.c_str());
201	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
202	    std::fprintf(stderr,
203	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
204	                 "after 20s; launching the debugger anyway\n",
205	                 jtag_port.c_str());
206	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
207	  // localhost, port 9104) instead of its default real-hardware adapter; without
208	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
209	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
210	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
211	}
